<section class="card overview-half" aria-labelledby="overview-demand-heading">
<div class="card-header"><div><p class="integration-kicker">Keywords & research</p><h2 id="overview-demand-heading">Demand to pursue</h2></div><a class="small" href="<?= $view->e($base) ?>/keywords/research">Research →</a></div>
<?php if ($evidence['near'] !== []): ?>
<h3 class="overview-subheading">Within reach in Google</h3><p class="muted small"><?= $evidence['nearCount'] ?> queries ranking 4–20 with at least 200 impressions</p>
<table class="table table-dense" data-no-table-controls><thead><tr><th scope="col">Query</th><th scope="col" class="num">Impressions</th><th scope="col" class="num">Position</th></tr></thead><tbody><?php foreach (array_slice($evidence['near'], 0, 3) as $row): ?><tr><td><?= $view->e($row->key) ?></td><td class="num"><?= number_format($row->metrics->impressions) ?></td><td class="num"><?= number_format($row->metrics->position, 1) ?></td></tr><?php endforeach; ?></tbody></table>
<?php endif; ?>
<?php foreach ($evidence['demand'] as $group): ?>
<details class="overview-research-group" open><summary><?= $view->e($group['locale']->label()) ?><span class="muted small"><?= $group['sample'] ?> saved keywords</span></summary>
<p class="muted small">Completed research fetched <?= $view->e($group['from']) ?> – <?= $view->e($group['to']) ?> UTC</p>
<dl class="overview-demand-totals"><div><dt>Tracked sample</dt><dd><?= $group['tracked'] ?> keywords · <?= number_format($group['trackedVolume']) ?> known monthly searches</dd></div><div><dt>Untracked sample</dt><dd><?= $group['untracked'] ?> keywords · <?= number_format($group['untrackedVolume']) ?> known monthly searches</dd></div></dl>
<?php if ($group['rows'] !== []): ?><table class="table table-dense" data-no-table-controls><thead><tr><th scope="col">Untracked keyword</th><th scope="col" class="num">Monthly volume</th><th scope="col">Evidence</th></tr></thead><tbody><?php foreach ($group['rows'] as $row): ?><tr><td><?= $view->e($row['keyword']->keyword) ?></td><td class="num"><?= $row['keyword']->searchVolume === null ? '—' : number_format($row['keyword']->searchVolume) ?></td><td><?= $row['kind'] === 'gap' ? 'Competitor gap' : ($row['kind'] === 'ranked' ? 'Saved ranking query' : 'Keyword idea') ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
</details>
<?php endforeach; ?>
<?php if ($evidence['cannibalization'] !== []): ?>
<h3 class="overview-subheading">Queries shared by multiple pages</h3><ul class="overview-evidence-list"><?php foreach ($evidence['cannibalization'] as $group): ?><li><strong><?= $view->e($group['query']) ?></strong><?php foreach ($group['pages'] as $page): ?><span class="overview-cell-note"><a href="<?= $view->e($base . '/pages/details?url=' . rawurlencode($page['url'])) ?>"><?= $view->e(preg_replace('#^https?://[^/]+#', '', $page['url']) ?: '/') ?></a> · <?= $page['impressions'] ?> impressions · <?= number_format($page['share'] * 100, 1) ?> % observed share · position <?= number_format($page['position'], 1) ?></span><?php endforeach; ?></li><?php endforeach; ?></ul>
<?php endif; ?>
<?php if ($evidence['near'] === [] && $evidence['demand'] === [] && $evidence['cannibalization'] === []): ?><p class="muted">No supported striking-distance queries, completed research or competing-page candidates for this period.</p><?php endif; ?>
<a href="<?= $view->e($base) ?>/keywords">Review tracked keywords →</a>
<?php if ($evidence['near'] !== [] || $evidence['demand'] !== [] || $evidence['cannibalization'] !== []): ?><details class="overview-about"><summary><?= $view->icon('info') ?>About this data</summary><?php if ($evidence['near'] !== []): ?><p>Within reach: queries at average position 4–20 with at least 200 impressions, within <?= $evidence['querySample'] ?> loaded queries · <?= $view->e($evidence['range']->fromString()) ?> – <?= $view->e($evidence['range']->toString()) ?>.</p><?php endif; ?><?php foreach ($evidence['demand'] as $group): ?><p><?= $view->e($group['locale']->label()) ?>: deduplicated within this market; tracking matches the same market. <?= $group['unknownVolume'] ?> keywords lack volume. Volumes are provider estimates for this saved sample, not total market demand.</p><?php endforeach; ?><?php if ($evidence['cannibalization'] !== []): ?><p>Shared queries: possible page competition, not proof of harm. From <?= $evidence['jointSample'] ?> loaded query/page pairs (maximum 5,000), with at least 200 query impressions and two top-20 pages sharing demand.</p><?php endif; ?></details><?php endif; ?>
</section>
